local IdolLive3D_FreeCameraMotion = Class('IdolLive3D_FreeCameraMotion')
-- 外部访问时使用:
-- local IdolLive3D_FreeCameraMotion = import('Game.IdolLive3D.IdolLive3D_FreeCameraMotion')



-- ========================================================


