-- ========================================================


function IdolLive3D_FreeCameraMotion:__init()
    self.isInit = false
    self.speedMultiples = {
        yaw = 1,
        pitch = 1,
        zoom = 1,
    }
end


function IdolLive3D_FreeCameraMotion:__delete()
    Object.Destroy( self.rootGo )
end


---@param centerPos_ UnityEngine.Vector3    @ 坐标轴初始点
---@param rawTF_ UnityEngine.Transform      @ 
---@param smoothTF_ UnityEngine.Transform   @ vcam tf; 本功能的 核心操作对象; 通过手动控制这个 tf 来实现 vcam 相机的运动;
function IdolLive3D_FreeCameraMotion:Init( idolLive3D_Camera_, centerPos_, rawTF_, vcam_, freeCameraTrackNodeParamsManager_, initCameraSpatialParams_, freeCameraActiveSpatialRange_ )

    self.idolLive3D_Camera = idolLive3D_Camera_

    -- ============================:
    -- 新建一些 辅助用的 go:
    self.rootGo = GameObject("_FreeCameraMotion_")
    self.rootGo.transform:SetParent( self.idolLive3D_Camera.controller.gameObject.transform )
    --- 
    local rawCenterGO = GameObject("rawCenter")
    self.centerTF = rawCenterGO.transform
    self.centerTF:SetParent(self.rootGo.transform)
    self.centerTF.position = centerPos_
    --- 仅响应 yaw 运动的 tf:
    local yawCenterGO = GameObject("yawCenter")
    self.yawRawCenterTF = yawCenterGO.transform
    self.yawRawCenterTF:SetParent(self.rootGo.transform)
    self.yawRawCenterTF.position = centerPos_
    --- yawRawCenterTF 的平滑版 tf:
    local yawSmoothCenterGO = GameObject("yawSmoothCenter")
    self.yawSmoothCenterTF = yawSmoothCenterGO.transform
    self.yawSmoothCenterTF:SetParent(self.rootGo.transform)
    self.yawSmoothCenterTF.position = centerPos_

    ---
    self.coord = {
        centerPos = centerPos_,
        upDir = Vector3.up, -- 后续配置
        forwardDir = Vector3.forward, -- 后续配置
        rightDir = Vector3.right, -- 后续配置
        mtx_World2Local = Matrix4x4.identity, -- 后续配置
        mtx_Local2World = Matrix4x4.identity, -- 后续配置
    }

    --- 
    assert( rawTF_ and vcam_ )
    self.rawTF = rawTF_
    self.smoothTF = vcam_.transform
    self.freeVCam = vcam_


    ------------------
    self:ChangeFreeCameraTrackNodeParamsManager( freeCameraTrackNodeParamsManager_ )
    self:ChangeActiveSpatialRange( freeCameraActiveSpatialRange_ )


    -- ============================:
    self.paramsExpand = KTool.GetComponent(self.controller.gameObject, typeof(LuaParametersExpand))
    assert( self.paramsExpand )
    self.t_speedCurve = LuaParametersReader.Read( self.paramsExpand, "t_speed", LuaParametersExpandType.Curve ) -- AnimationCurve


  
    -- 所有和 俯仰旋转 有关的参数:
    self.pitch = 
    {
        max = 25,   -- 俯仰角 上界 (向下仰视) -- todo: 未来走配表
        min = -30,  -- 俯仰角 下界 (向上俯视) -- todo: 未来走配表
        raw_t = 0.5,    -- [0,1], 上0下1, 可在 vcams 曲线上采样
        smooth_t = 0.5  -- [0,1], 上0下1, 可在 vcams 曲线上采样 (平滑值)
    }
    

    -- PosFree, PosLocked 通用的数据:
    -- 所有和 镜头拉伸 有关的参数:
    self._zoom =
    {
        raw_t   = 1.0, -- [0,1] 近0远1,
        smooth_t = 1.0, -- [0,1] 近0远1
    }


    self.smoothFov = 1.0

    -- ============= init vcam pos ===============:
    self:SetImmediately( initCameraSpatialParams_ )


    self.isInit = true
end




function IdolLive3D_FreeCameraMotion:OnDestroy()
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- ===============================================================


-- 设置自由轨道 中央点; 
---@param centerPos_ UnityEngine.Vector3 @ y值最好为 0
function IdolLive3D_FreeCameraMotion:SetCenterPos( centerPos_ )
    self.centerTF.position = centerPos_
    self.yawRawCenterTF.position = centerPos_
    self.yawSmoothCenterTF.position = centerPos_
    ---
    self.coord.centerPos = centerPos_
end 



function IdolLive3D_FreeCameraMotion:ChangeFreeCameraTrackNodeParamsManager( freeCameraTrackNodeParamsManager_ ) 
    assert( isNotNull(freeCameraTrackNodeParamsManager_) )
    self.idolLive3D_FreeCameraTrackNodeParamsManager = freeCameraTrackNodeParamsManager_
    -- 
    self.speedMultiples = self.idolLive3D_FreeCameraTrackNodeParamsManager.jsonData.speedMultiples
    --
    self.coord.upDir        = freeCameraTrackNodeParamsManager_.upDir.normalized
    self.coord.forwardDir   = freeCameraTrackNodeParamsManager_.forwardDir.normalized
    self.coord.rightDir     = freeCameraTrackNodeParamsManager_.rightDir.normalized
    ---
    self.coord.mtx_World2Local     = freeCameraTrackNodeParamsManager_.mtx_World2Local
    self.coord.mtx_Local2World     = freeCameraTrackNodeParamsManager_.mtx_Local2World
end 



function IdolLive3D_FreeCameraMotion:FindClosestTrackNodeParams(pos_) 
    self.idolLive3D_FreeCameraTrackNodeParamsManager:FindClosestTrackNodeParams(pos_)
end


function IdolLive3D_FreeCameraMotion:ChangeActiveSpatialRange( freeCameraActiveSpatialRange_ ) 
    assert( isNotNull(freeCameraActiveSpatialRange_) )
    self.activeSpatialRange = freeCameraActiveSpatialRange_
end



-- ===============================================================


function IdolLive3D_FreeCameraMotion:SetActive( isActive_ )
    KTool.SetActive( self.freeVCam.gameObject, isActive_ == true )
end 



function IdolLive3D_FreeCameraMotion:SetPriority( priority_ )
    self.freeVCam.Priority = checkNumber(priority_)
end


-- ===============================================================

-- 设置相机状态(瞬间):
function IdolLive3D_FreeCameraMotion:SetImmediately( initCameraSpatialParams_ )
    --printError("IdolLive3D_FreeCameraMotion - SetImmediately")
    assert( type(initCameraSpatialParams_) == "table" and isNotNull(initCameraSpatialParams_.yaw) and isNotNull(initCameraSpatialParams_.pitch) and isNotNull(initCameraSpatialParams_.zoom)  )
    ---
    self:_SetRaw_Yaw_ByVal( initCameraSpatialParams_.yaw )
    ---
    self:_SetRaw_Pitch( initCameraSpatialParams_.pitch )
    self.pitch.smooth_t = self.pitch.raw_t
    ---
    self:_SetRaw_Zoom( initCameraSpatialParams_.zoom )
    self._zoom.smooth_t = self._zoom.raw_t
    ---
    local currentNodeParams = self.idolLive3D_FreeCameraTrackNodeParamsManager:GetNodeParams(self.pitch.smooth_t)
    self:_SetRaw( currentNodeParams, false, false )
    self:_SetVCam( currentNodeParams, self.freeVCam, false ) -- 配置相机参数
    -- ===============================================    
    IdolLive3D_Utils.SyncPosAndRotation({ src = self.rawTF, dst = self.smoothTF })
    IdolLive3D_Utils.SyncPosAndRotation({ src = self.yawRawCenterTF,   dst = self.yawSmoothCenterTF })
end



-- 设置相机状态(平滑):
function IdolLive3D_FreeCameraMotion:SetSmooth( initCameraSpatialParams_ )
    --printError("IdolLive3D_FreeCameraMotion - SetSmooth")
    assert( type(initCameraSpatialParams_) == "table" and isNotNull(initCameraSpatialParams_.yaw) and isNotNull(initCameraSpatialParams_.pitch) and isNotNull(initCameraSpatialParams_.zoom)  )
    ---
    self:_SetRaw_Yaw_ByVal( initCameraSpatialParams_.yaw )
    ---
    self:_SetRaw_Pitch( initCameraSpatialParams_.pitch )
    ---
    self:_SetRaw_Zoom( initCameraSpatialParams_.zoom )
end




-- ===============================================================

function IdolLive3D_FreeCameraMotion:SelfUpdate()
    if self.isInit ~= true then 
        return
    end 

    self.pitch.smooth_t = Mathf.Lerp( self.pitch.smooth_t, self.pitch.raw_t, 0.1 )
    ---
    local currentNodeParams = self.idolLive3D_FreeCameraTrackNodeParamsManager:GetNodeParams(self.pitch.smooth_t)
    self:_SetRaw( currentNodeParams, true, true )
    self:_SetVCam( currentNodeParams, self.freeVCam, true ) -- 配置相机参数

    -- ===============================================    
    -- 目前 rawTF -> smoothTF 平滑组 没有被启用:  -- todo: 若未来也没被使用, 可考虑删去 rawTF...
    IdolLive3D_Utils.SyncPosAndRotation({ src = self.rawTF, dst = self.smoothTF })
end


-- ===============================================================

---@return number 返回 相机的角色的哪个方位角, [0,360], 在角色正前方为 0/360, 在角色右侧为 90, 后方为 180, 左侧为 270
function IdolLive3D_FreeCameraMotion:GetYaw( isRaw_ )
    local yawCenterForward = (isRaw_ == true) and self.yawRawCenterTF.forward or self.yawSmoothCenterTF.forward

    local angle = Vector3.SignedAngle( self.coord.forwardDir, yawCenterForward, self.coord.upDir )
    if angle < 0.0 then 
        angle = angle + 360
    end 
    return angle
end

---@return number 返回 pitch t 值, [0,1] 表示相机在 pitch 轨道上的位置; 通常 上端为 0, 下端为 1
function IdolLive3D_FreeCameraMotion:GetPitchT( isRaw_ )
    return (isRaw_ == true) and self.pitch.raw_t or self.pitch.smooth_t
end


---@return number 返回 zoom t 值, [0,1] 近端为 0, 远端为 1
function IdolLive3D_FreeCameraMotion:GetZoomT( isRaw_ )
    return (isRaw_ == true) and self._zoom.raw_t or self._zoom.smooth_t
end



-- ============================= 约束机位的可动区间 ==================================

function IdolLive3D_FreeCameraMotion:_SetRaw_Yaw_ByVal( yaw_ )
    self.yawRawCenterTF.rotation = Quaternion.LookRotation( self.coord.forwardDir, self.coord.upDir ) * Quaternion.Euler(0, yaw_, 0)

    if self.activeSpatialRange.yaw.isUse == true then 

        local tgtDir    = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.dir,       self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )
        local leftDir   = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.leftDir,   self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )
        local rightDir  = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.rightDir,  self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )

        --- 可动夹角太小, 等于不能动
        if self.activeSpatialRange.yaw.range < 1.0 then
            self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + tgtDir,  self.coord.upDir)
            return
        end

        local halfRange = self.activeSpatialRange.yaw.range * 0.5
        local angle = Vector3.SignedAngle( tgtDir, self.yawRawCenterTF.forward, self.coord.upDir )
        if angle < -halfRange then 
            self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + leftDir,  self.coord.upDir);
        elseif angle > halfRange then 
            self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + rightDir, self.coord.upDir);
        end
    end
end


function IdolLive3D_FreeCameraMotion:_SetRaw_Yaw_ByDelta( rotateDelta_ )
    if self.activeSpatialRange.yaw.isUse ~= true then 
        self.yawRawCenterTF:Rotate( self.coord.upDir, rotateDelta_, Space.World )  
        return
    end

    -------------------------
    -- !! 如果 range 特别大(比如 300), 可能导致单帧旋转过穿, 从左侧过穿到右侧..  以下代码是为规避此而问题而存在的
    local tgtDir    = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.dir,       self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )
    local leftDir   = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.leftDir,   self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )
    local rightDir  = IdolLive3D_Utils.TransformVector3( self.activeSpatialRange.yaw.rightDir,  self.coord.rightDir, self.coord.upDir, self.coord.forwardDir )

    --- 可动夹角太小, 等于不能动
    if self.activeSpatialRange.yaw.range < 1.0 then
        self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + tgtDir,  self.coord.upDir)
        return
    end

    ---
    local halfRange = self.activeSpatialRange.yaw.range * 0.5
    local oldAngle = Vector3.SignedAngle( tgtDir, self.yawRawCenterTF.forward, self.coord.upDir )
    self.yawRawCenterTF:Rotate( self.coord.upDir, rotateDelta_, Space.World )
    local newAngle = Vector3.SignedAngle( tgtDir, self.yawRawCenterTF.forward, self.coord.upDir )
    --printError( "old: " .. tostring(oldAngle) .. ", new: " .. tostring(newAngle) .. "; half: " .. tostring(halfRange) .. "; rotateDelta_ = " .. tostring(rotateDelta_) )
    if oldAngle < 0 and rotateDelta_ < 0 and (newAngle < -halfRange or newAngle > 0) then 
        --printError("--A--")
        self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + leftDir,  self.coord.upDir)
    elseif oldAngle > 0 and rotateDelta_ > 0 and (newAngle > halfRange or newAngle < 0) then
        --printError("--B--")
        self.yawRawCenterTF:LookAt( self.yawRawCenterTF.position + rightDir, self.coord.upDir)
    end
end



function IdolLive3D_FreeCameraMotion:_SetRaw_Pitch( pitch_ )
    self.pitch.raw_t = pitch_
    if self.activeSpatialRange.pitch.isUse == true then 
        self.pitch.raw_t = Mathf.Clamp( self.pitch.raw_t, self.activeSpatialRange.pitch.from, self.activeSpatialRange.pitch.to )
    end 
end


function IdolLive3D_FreeCameraMotion:_SetRaw_Zoom( zoom_ )
    self._zoom.raw_t = zoom_
    if self.activeSpatialRange.zoom.isUse == true then 
        self._zoom.raw_t = Mathf.Clamp( self._zoom.raw_t, self.activeSpatialRange.zoom.from, self.activeSpatialRange.zoom.to )
    end 
end




-- ===============================================================

function IdolLive3D_FreeCameraMotion:_SetRaw( trackNodeParams, isYawLerp, isZoomLerp )

    -- !!! 平滑 yaw 运动:  
    self.yawSmoothCenterTF.position = Vector3.Lerp(      self.yawSmoothCenterTF.position, self.yawRawCenterTF.position, isYawLerp and 0.23 or 1 )
    self.yawSmoothCenterTF.rotation = Quaternion.Lerp(   self.yawSmoothCenterTF.rotation, self.yawRawCenterTF.rotation, isYawLerp and 0.23 or 1 )  


    local dirHorizon = Vector3.ProjectOnPlane(self.yawSmoothCenterTF.forward, self.coord.upDir).normalized
    self.rawTF.position = self.coord.centerPos + dirHorizon * trackNodeParams.xzDistance + self.coord.upDir * trackNodeParams.cameraH
    -- ===

    local yOffset = Mathf.Tan(trackNodeParams.pitchDegree * Mathf.Deg2Rad ) * trackNodeParams.xzDistance

    self.centerTF.position = self.coord.centerPos + self.coord.upDir * ( trackNodeParams.cameraH - yOffset )

    self.rawTF:LookAt( self.centerTF, self.coord.upDir )

    -- !!! 用 相机前后运动 来实现 镜头拉伸 (的一半效果): 
    self._zoom.smooth_t = Mathf.Lerp( self._zoom.smooth_t, self._zoom.raw_t, isZoomLerp and 0.25 or 1 )
    local moveOffset = KTool.Remap( 0, 1.0, trackNodeParams.minDistanceOffset, trackNodeParams.maxDistanceOffset, self._zoom.smooth_t)
    self.rawTF.position = self.rawTF.position - self.rawTF.forward * moveOffset
end



function IdolLive3D_FreeCameraMotion:_SetVCam( trackNodeParams, vcam_, isLerp )
    if isNotNull(vcam_) then

        -- !!! 用 fov 来实现 镜头拉伸 (的一半效果):
        local rawFov = KTool.Remap( 0, 1, trackNodeParams.minFov, trackNodeParams.maxFov, self._zoom.raw_t )

        self.smoothFov = Mathf.Lerp( self.smoothFov, rawFov, isLerp and 0.1 or 1 )
        ---
        local lens = vcam_.m_Lens 
        lens.FieldOfView = self.smoothFov
        vcam_.m_Lens = lens
    end
end



-- ===============================================================

-- 触发: 偏航 (旋转观察 idol )
function IdolLive3D_FreeCameraMotion:YawByDelta( rotateDelta_ )

    local threshold = 40  -- todo: 速度上界, 33, 未来走配表
    rotateDelta_ = rotateDelta_ * 2 * self.speedMultiples.yaw -- todo: 移动端加速
    
    -- 反二项曲线, 让响应变快:
    local w = Mathf.Clamp01( KTool.Remap( 0, threshold, 0, 1, Mathf.Abs(rotateDelta_) ))
    w = 1 - (1-w)*(1-w)
    local rotateDelta = w * threshold * (rotateDelta_<=0 and -1 or 1)

    self:_SetRaw_Yaw_ByDelta( rotateDelta )
end 



-- 触发: 俯仰
function IdolLive3D_FreeCameraMotion:PitchByDelta( rotateDelta_ )

    -- 约束俯仰角极值
    local threshold = 50  -- todo: 速度上界, 未来走配表
    rotateDelta_ = Mathf.Clamp( rotateDelta_ * self.speedMultiples.pitch, -threshold, threshold )

    local tSpeedScale = 1.4
    local tSpeed = self.t_speedCurve:Evaluate( self.pitch.raw_t )
    rotateDelta_ = rotateDelta_ * tSpeed * tSpeedScale

    local min = self.pitch.min
    local max = self.pitch.max

    local oldPitch_t = self.pitch.raw_t
    local tmpDegree = KTool.Remap( 0.0, 1.0, min, max,  oldPitch_t )
    tmpDegree = tmpDegree - rotateDelta_
    tmpDegree = Mathf.Clamp( tmpDegree, min, max )
    
    self:_SetRaw_Pitch( KTool.Remap( min, max, 0.0, 1.0, tmpDegree ) )
    local t_offset = Mathf.Abs( self.pitch.raw_t - oldPitch_t )

    ---- 主动将 zoom.raw_t 约束回 range_t, 从而保证在 vcams轨道的每个点上, 都能获得正确的 伸缩幅度: -- zoom.raw_t 其实也走了条曲线
    local currentNodeParams = self.idolLive3D_FreeCameraTrackNodeParamsManager:GetNodeParams(self.pitch.smooth_t)
    self._zoom.raw_t = Mathf.Clamp01( Mathf.MoveTowards( self._zoom.raw_t, currentNodeParams.range_t, t_offset * 0.7 ) )
    self:_SetRaw_Zoom( self._zoom.raw_t )
end





-- 触发: 镜头缩放
function IdolLive3D_FreeCameraMotion:ZoomByDelta( deltaPinch_ )

    local pinchVal = deltaPinch_ * self.speedMultiples.zoom
    if IdolLive3D_States.isWindowsPlatform == true then 
        pinchVal = pinchVal * 0.02
    else    
        pinchVal = pinchVal * 0.02 * 0.2
    end 
    self:_SetRaw_Zoom( Mathf.Clamp01( self._zoom.raw_t + pinchVal ) ) -- [0,1]
end


-- ===============================================================================


-- 找出 自由相机轨道中, 离 pos_ 最近的位置, 将 free vcam 设置上去;
---@param pos_ UnityEngine.Vector3 @ 场景中任意pos, 通常是一个 timeline vcam 的pos 
---@param decreteFreeCameraSpatialParams_ table | nil @ 允许为 nil, 类型为 c# 中的 IdolLive3D.DecreteFreeCameraSpatialParams
function IdolLive3D_FreeCameraMotion:CloseToTgtPos( pos_, decreteFreeCameraSpatialParams_ )
    if self.isInit ~= true or isNull(self.idolLive3D_FreeCameraTrackNodeParamsManager) then 
        printError("koko - 不符合调用条件")
        return 
    end 

    local pos = IdolLive3D_Utils.MatrixMult(self.coord.mtx_World2Local, pos_)
    local cameraSpatialParams = self.idolLive3D_FreeCameraTrackNodeParamsManager:FindClosestTrackNodeParams(pos)

    -- 允许美术定制 yaw/pitch/zoom 各个值
    local dp = decreteFreeCameraSpatialParams_
    if isNotNull(dp) then 
        if dp.isUseYaw == true and type(dp.yaw) == "number" then 
            cameraSpatialParams.yaw = dp.yaw
        end 
        if dp.isUsePitch == true and type(dp.pitch) == "number" then 
            cameraSpatialParams.pitch = dp.pitch
        end 
        if dp.isUseZoom == true and type(dp.zoom) == "number" then 
            cameraSpatialParams.zoom = dp.zoom
        end 
    end 

    self:SetImmediately( cameraSpatialParams )
end



return IdolLive3D_FreeCameraMotion
